customMethods.script:

system.perspective.print(path)
if not isinstance(path, str) or (isinstance(path, str) and "." not in path):
	return path

node = self.session.custom

steps = payload[0].split(".")
end = steps.pop()

for step in steps:
	node = node[step]

node[end] = payload[1]

return node

messageHandlers.script:
node = self.indirect(payload["path"])

if payload["mode"] == "set":

	node = self.indirect(payload["value"])

else:

	node += self.indirect(payload["value"])
	return
